describe('ToolRegistry inputSchema validation', () => {
  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect(executorCalls).toBe(0);
    expect(response.result).toMatch(/required/i);
    expect(response.result).toContain('location');
  });
});

private formatValidationError(errors: ValidateFunction['errors']): string {
  if (!errors || errors.length === 0) {
    return 'Invalid tool input';
  }
  const messages = errors.map(err => {
    const path = err.instancePath ? err.instancePath.replace(/^\//, '').replace(/\//g, '.') : '';
    if (err.keyword === 'required' && err.params && 'missingProperty' in err.params) {
      const prop = String(err.params.missingProperty);
      const fullPath = path ? `${path}.${prop}` : prop;
      return `Missing required property: ${fullPath}`;
    }
    const target = path || 'input';
    return `${target} ${err.message ?? 'is invalid'}`;
  });
  return `Invalid tool input: ${messages.join('; ')}`;
}

has(name: string): boolean {
  return this.tools.has(name);
}

/** Validates input against inputSchema, returning a rejection ToolResponse on failure; throws only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }
  const definition = this.resolveDefinition(tool.definitionSource);
  let validator = tool.staticValidator;
  if (!validator) {
    const schema = definition.inputSchema ?? {};
    if (schema && typeof schema === 'object') {
      validator = this.validatorCache.get(schema);
    }
    if (!validator) {
      validator = this.compileSchema(definition.name, schema);
      if (schema && typeof schema === 'object') {
        this.validatorCache.set(schema, validator);
      }
    }
  }

  const isValid = validator(input);
  if (!isValid) {
    const result = this.formatValidationError(validator.errors);
    log.warn('tool', 'tool input validation failed', {
      name,
      inputKeys: Object.keys(input),
    });
    return {result};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);
  log.info('tool', 'execution complete', {
    name,
    rawType: typeof rawResult,
    clientMessageCount: response.clientMessages?.length ?? 0,
    clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
    suppressAssistantResponse: response.suppressAssistantResponse ?? false,
  });
  return response;
}

